(7433774, 1175164, 86447, '<td valign="top">O!  <br/> <br/>Gorgeous!<br/> <br/>I love the processing that tops off your brilliant photography.</td>', 'O!   Gorgeous! I love the processing that tops off your brilliant photography.', '2016-02-01 00:20:24.000000', NULL, 1),
(7433785, 1174990, 96751, '<td valign="top">What a cool artifact.</td>', 'What a cool artifact.', '2016-02-01 00:35:32.000000', NULL, 1),
(7433786, 1175092, 96751, '<td valign="top">Beautifully lit.</td>', 'Beautifully lit.', '2016-02-01 00:36:06.000000', NULL, 1),
(7433788, 1174928, 96751, '<td valign="top">I like the tilt but not the composition - I imagine this would be stronger as a square crop.</td>', 'I like the tilt but not the composition - I imagine this would be stronger as a square crop.', '2016-02-01 00:38:49.000000', NULL, 1),
(7433789, 1175069, 96751, '<td valign="top">That giant white pricetag just wrecks it for me</td>', 'That giant white pricetag just wrecks it for me', '2016-02-01 00:39:23.000000', NULL, 1),
(7433795, 1175221, 96751, '<td valign="top">The pots are cool. Not sure about the background...it''s far more interesting than the subjects :)</td>', 'The pots are cool. Not sure about the background...it''s far more interesting than the subjects :)', '2016-02-01 00:46:38.000000', NULL, 1),
(7433813, 1175086, 103032, '<td valign="top">Guessing .223, .22LR, and .45fmj.  Works for me.  Not a member, so can only offer a comment.  I like that you included a variety, makes it more interesting to look around.  Like the black background and reflections; accentuates the brass.  If I was a voting member, I would have started this with a 7; maybe a bump after reviewing the rest.  Good luck.</td>', 'Guessing .223, .22LR, and .45fmj.  Works for me.  Not a member, so can only offer a comment.  I like that you included a variety, makes it more interesting to look around.  Like the black background and reflections; accentuates the brass.  If I was a voting member, I would have started this with a 7; maybe a bump after reviewing the rest.  Good luck.', '2016-02-01 02:58:57.000000', NULL, 1),
(7433814, 1175144, 103032, '<td valign="top">Cool seeing something I recognize.  Bronze statue in front of the District Courthouse in Tacoma.  My only critique would be if you had went for a lower point of view, it would have made a more "dramatic" impact...  But that''s just an opinion.  Not a member, so can only offer a comment.  Best of luck on the voting.</td>', 'Cool seeing something I recognize.  Bronze statue in front of the District Courthouse in Tacoma.  My only critique would be if you had went for a lower point of view, it would have made a more "dramatic" impact...  But that''s just an opinion.  Not a member, so can only offer a comment.  Best of luck on the voting.', '2016-02-01 03:08:34.000000', NULL, 1),
(7433840, 1175035, 179608, '<td valign="top">10, cause is much better than mine :)</td>', '10, cause is much better than mine :)', '2016-02-01 08:33:21.000000', NULL, 1),
(7433860, 1175136, 181814, '<td valign="top">This is very good, with nice clarity and very well composed, it is one of my favorites.</td>', 'This is very good, with nice clarity and very well composed, it is one of my favorites.', '2016-02-01 09:08:40.000000', NULL, 1),
(7433864, 1175098, 181814, '<td valign="top">I like the diagonal composition and the focus is sharp and clear.</td>', 'I like the diagonal composition and the focus is sharp and clear.', '2016-02-01 09:09:51.000000', NULL, 1),
(7434037, 1175096, 99835, '<td valign="top">Very nice photo was my highest rated one</td>', 'Very nice photo was my highest rated one', '2016-02-01 18:57:30.000000', NULL, 1),
(7434039, 1174988, 181814, '<td valign="top">I like the depth of field, the composition and the focus but I think the penny needs a little more contrast or saturation.</td>', 'I like the depth of field, the composition and the focus but I think the penny needs a little more contrast or saturation.', '2016-02-01 19:09:31.000000', NULL, 1),
(7434041, 1175111, 181814, '<td valign="top">In my opinion this doesn''t abide by the contest description. I also think the top of the helmet is brownout and the lower part of the photograph is under exposed. The overall photograph seems to be a bit soft and out of focus.</td>', 'In my opinion this doesn''t abide by the contest description. I also think the top of the helmet is brownout and the lower part of the photograph is under exposed. The overall photograph seems to be a bit soft and out of focus.', '2016-02-01 19:14:14.000000', NULL, 1),
(7434042, 1174984, 181814, '<td valign="top">The focus and exposure are good but the crop doesn''t seem right to me, I would like to see more of the statue and if you are going to make it into a head shot maybe a square chop but still showing more of the neck, I don''t like how the top and bottom are cutoff.</td>', 'The focus and exposure are good but the crop doesn''t seem right to me, I would like to see more of the statue and if you are going to make it into a head shot maybe a square chop but still showing more of the neck, I don''t like how the top and bottom are cutoff.', '2016-02-01 19:17:39.000000', NULL, 1),
(7434044, 1175072, 181814, '<td valign="top">I like the brass bowl but I don''t like that you presented it blurred and out of focus.</td>', 'I like the brass bowl but I don''t like that you presented it blurred and out of focus.', '2016-02-01 19:20:03.000000', NULL, 1),
(7434045, 1175069, 181814, '<td valign="top">I know these are copper  but I think the way they are presented is distracting. I think maybe a solid background without the price tag and in better focus, with some of the dust particles edited out would make them look much better.</td>', 'I know these are copper  but I think the way they are presented is distracting. I think maybe a solid background without the price tag and in better focus, with some of the dust particles edited out would make them look much better.', '2016-02-01 19:23:25.000000', NULL, 1),
(7434334, 1175193, 181814, '<td valign="top">The background color really goes good with the subject in the foreground.</td>', 'The background color really goes good with the subject in the foreground.', '2016-02-02 21:33:08.000000', NULL, 1),
(7434590, 1175092, 101668, '<td valign="top">So smart, you are. Beautiful</td>', 'So smart, you are. Beautiful', '2016-02-04 08:05:35.000000', NULL, 1),
